class SimulatedFFI():
    def __init__(self):
        self.fcl = FCL()
        self.bhv_extractor = BehavioralExtractor()

    def simulated_fuzzy_inference(self, trx, bhv):
        self.bhv_extractor.bhv = bhv
        trx_att = {
            'trx_type': trx.get('TRANSACTIONTYPENAME'),
            'trx_amount': trx.get('TRANSACTIONAMOUNT')
        }
        trx.update(self.bhv_extractor.add_bank_fuzzy_bhv_params(trx_att))

        _activation, _class, _rule_activation, fcl_id = self.fcl.predict(trx)
        fired_rules = _rule_activation
        if any([item!=0 for item in fired_rules]):
            id_max = [i + 1 for i in range(len(fired_rules)) if fired_rules[i] == max(fired_rules)]
            return id_max
        else:
            return 'no fired rule'


if __name__ == '__main__':
    ffi = SimulatedFFI()
    result = ffi.simulated_fuzzy_inference(trx, bhv)
    print(result)
    for thread in threading.enumerate():
        if thread.name != 'MainThread':
            thread.cancel()

